We start by proving the following 2 auxiliary statements:

\begin{lemma}\label{lem:diag}
If $C =  (v_0 \rightarrow u^\perp_1 \rightarrow v_1 \rightarrow u^\parallel_2 \rightarrow v_2\rightarrow \ldots  u^\parallel_{\ell} \rightarrow v_{0})$ is a minimal $\Tilde{f}$-violating cycle with $\ell \geq 2$, then \begin{equation}
    \prod_{i=1}^\ell \left(|a_{i,i}| + \frac{\norm{u_i^\perp}}{\norm{v_i^\perp}}\right) \leq 1.2 \cdot e^{-\tilde{w}_0(C)}. \label{eq:r1}
\end{equation}
\end{lemma}
\begin{proof}
Since $C$ is an $\Tilde{f}$-violating cycle, \begin{equation}
    e^{-\Tilde{w}_0(C)} = \frac{\norm{u_1^\perp}}{\norm{v_1^\perp}} \cdot \prod_{i=2}^\ell |a_{i, i}| \geq \Tilde{f}(\ell). \label{eq:a4}
\end{equation}

Define $x_{i, 0} := \frac{\norm{u_i^\perp}}{\norm{v_i^\perp}}$ and $x_{i, 1} := |a_{i,i}|$ for all $i \in [\ell]$. Then we can decompose the LHS of~\eqref{eq:r1} as follows:
\begin{align*}
      \prod_{i=1}^\ell \left(|a_{i,i}| + \frac{\norm{u_i^\perp}}{\norm{v_i^\perp}}\right) = \sum_{Z \subseteq [\ell]} \prod_{i \in Z}x_{i, 0} \cdot \prod_{i \notin Z} x_{i, 1} =: \sum_{Z \subseteq [\ell]}  w(Z) ,
\end{align*}
We now upper bound $w(Z)$ for all $Z \neq \{1\}$ based on the cardinality of $Z$.  
For the empty set, i.e., $|Z| = 0$, since Algorithm \ref{alg:exchr} did not return a cycle in Stage 1, $w(Z) =  \prod_{i=1}^\ell |a_{i,i}| = e^{-w_0(C)} \leq f(\ell)$.

Consider a subset $Z$ with $|Z| = k$ where $k \geq 2$. We define a cycle $C_Z$ such that $C_Z$ contains the same arcs as $C$ but a vertex $u_i \in C\backslash S$ is present as a perpendicular vertex in $C_Z$ if and only if $u \in Z$. Then $w(Z) = e^{-\Tilde{w}_0(C_Z)}$. Let the distance between successive perpendicular vertices in $C_Z$ be $b_1, b_2, \ldots, b_k$. Then $\sum_{i=1}^k b_i = \ell$ and by Lemma \ref{lem:parts},  $w(Z) =  e^{-\Tilde{w}_0(C_Z)} \leq \prod_{i=1}^k \Tilde{f}(b_i)$.

Since $C_Z$ has the same structure as $C$, we can completely characterize $C_Z$ by the first vertex among $u_1, u_2, \ldots, u_\ell$ which is perpendicular, and the distances between successive perpendicular vertices in $C_Z$, i.e., $b_1, b_2, \ldots, b_k$. There are only $\ell$ options for the first perpendicular vertex. Therefore,
\begin{align}
   \sum_{Z:|Z| = k} w(Z) \leq \ell \cdot \sum_{\substack{\sum_{j=1}^k b_j = \ell \\
   b_1, b_2, \ldots, b_k \geq 1}} \prod_{i=1}^k \Tilde{f}(b_i) \leq \ell \cdot \binom{\ell-1}{k-1}\cdot \Tilde{f}(\ell-k+1) \leq \frac{\Tilde{f}(\ell)}{\ell^8}\,. \label{eq:a5}
\end{align}

For a subset with one element, i.e., $Z = \{x\}$, $x \neq 1$, $-\log w(Z)$ is the same as the weight of the cycle
\begin{equation*}
    C_x := (v_0 \rightarrow u_1^\parallel \rightarrow v_1 \rightarrow \ldots u_x^\perp \rightarrow v_2 \rightarrow \ldots \rightarrow u_\ell^\parallel \rightarrow v_0) \,.
\end{equation*}
Combining $C_x$ with $C$, we get two cycles
\begin{align*}
    C_x^{(1)} &= (v_0 \rightarrow u_1^\perp \rightarrow v_1 \rightarrow \ldots u_x^\perp \rightarrow v_2 \rightarrow \rightarrow \ldots u_\ell^\parallel \rightarrow v_0) \\
     C_x^{(2)} &= (v_0 \rightarrow u_1^\parallel \rightarrow v_1 \rightarrow \ldots u_x^\parallel \rightarrow v_2 \rightarrow \ldots \rightarrow u_\ell^\parallel \rightarrow v_0)\,, 
\end{align*}
such that $\Tilde{w}_0(C) \cdot \Tilde{w}_0(C_x) = \Tilde{w}_0(C_x^{(1)}) \cdot \Tilde{w}_0(C_x^{(2)}))$.
By Lemma \ref{lem:parts}, we know that $e^{-\Tilde{w}_0(C_x^{(1)})} \leq \Tilde{f}(x-1)\Tilde{f}(\ell-x+1)$. Also, since $C_x^{(2)}$ only contains parallel vectors, $\Tilde{w}_0(C_x^{(2)}) =w_0(C_x^{(2)})$; and since $C_x^{(2)}$ is not $f$-violating, $e^{-\Tilde{w}_0(C_x^{(2)})} \leq f(\ell)$.
Therefore, $e^{-\Tilde{w}_0(C) - \Tilde{w}_0(C_x)} \leq \Tilde{f}(x-1)\Tilde{f}(\ell-x+1) \cdot f(\ell)$. $C$ being $\tilde{f}$-violating implies $e^{-\Tilde{w}_0(C)} \geq \Tilde{f}(\ell)$, and therefore $e^{-\Tilde{w}_0(C)} \leq  \Tilde{f}(x-1)\Tilde{f}(\ell-x+1) f(\ell)/\Tilde{f}(\ell)$.

Summing over all choices of $x$, we get
\begin{equation}
   \sum_{Z, |Z| = 1} w(Z) =  \sum_{x=2}^\ell e^{-\Tilde{w}_0(C_x)} \leq \sum_{x = 2}^\ell \frac{\Tilde{f}(x-1)\Tilde{f}(\ell-x+1) f(\ell)}{\Tilde{f}(\ell)} \leq \frac{4f(\ell)}{\ell} \,. \label{eq:a6}
\end{equation}
Combining~\eqref{eq:a4}, ~\eqref{eq:a5}, and~\eqref{eq:a6}, we get
\begin{align*}
    \prod_{i=1}^\ell \left(|a_{i,i}| + \frac{\norm{u_i^\perp}}{\norm{v_i^\perp}}\right) &= \sum_{Z \subseteq [\ell]}  w(Z) \leq w(\emptyset) + \sum_{Z: |Z| = 1} w(Z) + \sum_{Z: |Z| \geq 2} w(Z) \\
    &\leq f(\ell) + e^{-\Tilde{w}_0(C)} + \frac{4 f(\ell)}{\ell}  + \frac{\Tilde{f}(\ell)}{\ell^8}\,.
\end{align*}
Since $e^{-\Tilde{w}_0(C)} \geq \Tilde{f}(\ell) \geq (\ell !)^4 \cdot f(\ell)$,
\begin{align*}
    \prod_{i=1}^\ell \left(|a_{i,i}| + \frac{\norm{u_i^\perp}}{\norm{v_i^\perp}}\right) &\leq e^{-\Tilde{w}_0(C)} \left(1+ \frac{3}{(\ell !)^4} + \frac{1}{\ell^8}\right) \leq 1.2 \cdot e^{-\Tilde{w}_0(C)}.
\end{align*}
\end{proof}

\begin{lemma} \label{lem:permw}
Let $C =  (v_0 \rightarrow u^\perp_1 \rightarrow v_1 \rightarrow u^\parallel_2 \rightarrow v_2\rightarrow \ldots  u^\parallel_{\ell} \rightarrow v_{0})$ be a minimal $\Tilde{f}$-violating cycle in $\widetilde{G}(S)$ with $\ell \geq 2$ and let $W_C$ be a matrix with $[W_C]_{i,j} = |a_{i,j}| + \frac{\norm{u_i^\perp}}{\norm{v_j^\perp}}$, then \begin{equation*}
   \perm(W_C) \leq 1.56 \cdot \frac{\norm{u_1^\perp}}{\norm{v_1^\perp}} \cdot \prod_{i=2}^\ell |a_{i, i}| \,.
\end{equation*}
\end{lemma}
\begin{proof}
Define $z_1 := \frac{\norm{u_1^\perp}}{\norm{v_1^\perp}}$, $p_1 = \perp$, and $z_i := |a_{i,i}|$, $p_i = \parallel$ for all $i \geq 2$.

We show upper bounds on the absolute value of each entry of $W_C$ as a function of $z_i$'s. Consider the $i,j$-th entry of $W_C$. For $i > j$, let $C_{i,j}^\perp := (u_i^\perp \rightarrow v_j \rightarrow u_{j+1}^{p_{j+1}} \rightarrow v_{j+1}\rightarrow \ldots  v_{i-1} \rightarrow u_i^{\perp})$. $C_{i,j}^{\perp}$ is a cycle of with $2(i-j)$ hops and $V(C_{i,j}^\perp) \subset V(C)$. $C$ being a minimal $\Tilde{f}$-violating cycle implies that $C_{i,j}^\perp$ is not an $\Tilde{f}$-violating cycle. Therefore, $e^{-\tilde{w}_0(C_{i,j}^\perp)} = \frac{\norm{u_i^\perp}}{\norm{v_j^\perp}} \cdot \prod_{s = j+1}^{i-1} z_s < \Tilde{f}(i-j)$.
This implies
\begin{equation}
    \frac{\norm{u_i^\perp}}{\norm{v_j^\perp}} < \frac{\Tilde{f}(i-j)}{\prod_{s = j+1}^{i-1} z_s}\,.
\end{equation}
Similarly for $j = \ell$, we have $ \frac{\norm{u_i^\perp}}{\norm{v_0^\perp}} < \frac{\Tilde{f}(i)}{\prod_{s = 1}^{i-1} z_s}\,.$

Similarly, let $C_{i,j}^\parallel := (u_i^\parallel \rightarrow v_j \rightarrow u_{j+1}^{p_{j+1}} \rightarrow v_{j+1}\rightarrow \ldots  v_{i-1} \rightarrow u_i^{\parallel})$. Again, using the fact that $C_{i,j}^\parallel$ is not $\Tilde{f}$-Violating we get \begin{equation}
    |a_{i, j}| < \frac{\Tilde{f}(i-j)}{\prod_{s = j+1}^{i-1} z_s} \,,
\end{equation}
for any $i > j$ and for $j = \ell$, we have $ a_{i, 0} < \frac{\Tilde{f}(i)}{\prod_{s = 1}^{i-1} z_s}\,.$

For $i < j < \ell$, let $C^\perp_{i,j} := (v_0 \rightarrow u_1^{p_i} \rightarrow v_1\rightarrow \ldots u_i^{\perp} \rightarrow v_j\rightarrow \ldots  u_{\ell}^{p_{\ell}} \rightarrow v_{0})$. Again, $C^\perp_{i,j}$ is a cycle with $2(\ell - j+i)$ hops and which is not $\Tilde{f}$-violating. Therefore, \begin{equation}
   \frac{\norm{u_i^{\perp}}}{\norm{v_j^{\perp}}} \cdot \prod_{s = 1}^{i-1} z_s \cdot \prod_{s = j+1}^{\ell} z_s < \Tilde{f}(\ell - j + i). \label{eq:2}
\end{equation}
Since $C$ is an $\Tilde{f}$-violating cycle, we also have \begin{equation}
    e^{-\tilde{w}_0(C)} = \prod_{s = 1}^\ell z_s > \Tilde{f}(\ell)\,. \label{eq:4}
\end{equation}
Combining~\eqref{eq:2} and~\eqref{eq:4} gives
 \begin{align*}
     \frac{\norm{u_i^{\perp}}}{\norm{v_j^{\perp}}} &< \frac{\Tilde{f}(\ell-j+i)}{\Tilde{f}(\ell)} \cdot \prod_{s=i}^j z_s \,.
\end{align*}
Similarly, for $i < j < \ell$,
 \begin{align*}
     |a_{i, j}| &< \frac{\Tilde{f}(\ell-j+i)}{\Tilde{f}(\ell)} \cdot \prod_{s=i}^j z_s \,.
\end{align*}\
Define $x_1 := (|a_{1,1}| + \frac{\norm{u_1^\perp}}{\norm{v_1^\perp}})/ \frac{\norm{u_1^\perp}}{\norm{v_1^\perp}} $ and $x_i :=(|a_{i,i}| + \frac{\norm{u_i^\perp}}{\norm{v_i^\perp}})/ |a_{i,i}|$ for $i \geq 2$. Then $x_i \geq 1$ and the $i$-th diagonal entry of $W_C$ is $x_i \cdot z_i$.

Let $B_{\ell}$ be the matrix obtained by applying the following operations to $W_C$ 
\begin{itemize}
    \item Multiply the last column by $z_1$ and for $j > 1$, divide the $j$-th column by $\prod_{s=2}^{j} z_s$
    \item Divide the first row by $z_1$ and for $i > 1$, multiply the $i$-th row by $\prod_{s = 2}^{i-1} z_s$
    \item Divide the last column by $\prod_{i=1}^\ell z_i$.
    \item Divide the $j$-th column by $x_j$.
\end{itemize}
Then $|\perm(W_C)| = (\prod_{i=1}^\ell x_i z_i) \cdot |\perm(B_{\ell})|$, and $B_\ell$ satisfies the following properties:
\begin{itemize}
    \item $b_{i,i}$ = 1 for all $i \in [\ell]$,
    \item $|b_{i,j}| \leq 2 \cdot \Tilde{f}(i-j)/x_j \leq 2\cdot  \Tilde{f}(i-j)$ for all $j < i \leq \ell$, and
    \item $|b_{i,j}| \leq 2\cdot \Tilde{f}(\ell - j + i)/(\Tilde{f}(\ell)x_j) \leq 2\cdot \Tilde{f}(\ell - j + i)/\Tilde{f}(\ell)$ for all $i < j \leq \ell$.
\end{itemize}
If $\ell = 1$, $\perm(B_\ell) = 1$ and for $\ell \geq 2$, Lemma \ref{lem:perm} gives $\perm(B_\ell) \leq 1.3$. Therefore, we have \begin{equation*}
    \perm(W_C) \leq 1.3 \cdot \prod_{i=1}^\ell x_i z_i = 1.3\cdot  \prod_{i=1}^\ell \left(|a_{i,i}| + \frac{\norm{u_i^\perp}}{\norm{v_i^\perp}}\right) \leq 1.3 \cdot 1.2 \cdot \frac{\norm{u_1^\perp}}{\norm{v_1^\perp}} \cdot \prod_{i=2}^\ell |a_{i, i}| = 1.56 \cdot e^{-\tilde{w}_0(C)}\;,
\end{equation*}
where the last inequality follows from Lemma \ref{lem:diag}.
\end{proof}

With the above in mind, we are now ready to prove the main statement:

\begin{proof}
If $|C| = 2$, then let $C = (u^\perp \rightarrow v)$. Since $C$ is an $\Tilde{f}$-violating cycle, $e^{-\Tilde{w}_0(C)} = \frac{\norm{u^\perp}}{\norm{v^\perp}} > \Tilde{f}(1) \geq 2$. By Lemma \ref{lem:weight_wa0}, \begin{equation*}
\frac{\vol(S-v+u)}{\vol(S)} =  \sqrt{a_{uv}^2 + \frac{\norm{u^\perp}^2}{\norm{v^\perp}^2} }\geq e^{-\Tilde{w}_0(C)} \geq 2.
\end{equation*}
This concludes the proof when $C$ has $2$ arcs.

Now consider the case when $C$ has at least $4$ arcs. By Corollary~\ref{cor:one}, we can assume that $C$ contains exactly one perpendicular vertex.
Let $C = ( u_1^\perp \rightarrow v_1 \rightarrow u_2^\parallel \rightarrow v_2\rightarrow \ldots  u_{\ell}^\parallel \rightarrow v_{\ell} \rightarrow u_1^\perp)$, where $\ell \geq 2$, $v_i \in S$, and $v_i \rightarrow u_{i+1}$ is an arc in $G(S)$.

Define $T := S \Delta C$, $X := C \backslash S = \{u_1, u_2, \ldots, u_\ell\}$, and $Y := S \cap C = \{v_1, v_2, \ldots, v_\ell \}$, and let $S\backslash Y = \{v_{\ell+1}, \ldots, v_{r}\}$. Let $\proj$ denote the projection matrix orthogonal to the span of $S\backslash Y$.

Then \begin{align*}
    \frac{\vol(T)}{\vol(S)} =  \frac{\vol(\{S \backslash Y\} \cup X)}{\vol(\{S\backslash Y\} \cup Y)} = \frac{\vol(u_1, u_2, \ldots,  u_\ell, v_{\ell+1}, \ldots, v_{r})}{\vol( v_1,  v_2, \ldots, v_\ell, v_{\ell+1}, \ldots,  v_r)} \,.
\end{align*}
Note that for any set of vectors $\{x_1, \ldots, x_\ell\}$, 
\[\vol(x_1, x_2, \ldots, x_\ell, v_{\ell+1}, \ldots, v_{r}) = \vol(\proj x_1, \proj x_2, \ldots, \proj x_\ell) \cdot \vol(v_{\ell+1}, \ldots, v_{r}).\]
Applying this to the sets $X$ and $Y$, we get
\begin{align*}
    \frac{\vol(T)}{\vol(S)} =  \frac{\vol(\proj u_1, \proj u_2, \ldots, \proj u_\ell)}{\vol(\proj v_1, \proj v_2, \ldots, \proj v_\ell)} =  \frac{\vol(\proj X)}{\vol(\proj Y)}\;.
\end{align*}

By definition, $u_i = \sum_{j=1}^r a_{i,j} v_j + u_i^\perp$. Taking the projection of $u_i$ orthogonal to $\Span(S\backslash Y)$, we get $\proj u_i = \sum_{j = 1}^{\ell} a_{i,j} \proj v_j + u_i^\perp$, since $Pv_{j} = 0$ for all $j > \ell$.
So we can decompose each vector $\proj u_i$ into a sum of $\ell+1$ vectors, i.e., $\proj u_i = \sum_{j=0}^\ell u_{i}^{(j)}$
where
\begin{itemize}
    \item $u_{i}^{(0)} := u_i^\perp$ for all $i$, and
    \item $u_{i}^{(j)} := a_{i, j} \proj v_j$.
\end{itemize}
Note that for any $i_1, i_2 \in [\ell]$, the vectors $u_{i_1}^{(j)}$ and $u_{i_2}^{(j)}$ are linearly dependent for any $j > 0$.

Let $I_C$ denote the tuple $(0,2,3, \ldots, \ell)$. Using Observation \ref{obs:volume_triangle}, we can lower bound $\vol(\proj X)$ as
\begin{equation}
    \vol(\proj X) \geq \vol(\,u_{1}^{(0)}, \, u_{2}^{(2)}, \ldots, \,u_{\ell}^{(\ell)}) \; - \sum_{\substack{i_1, i_2, \ldots, i_\ell \in \{0,1,\dots,\ell\} \\ (i_1, i_2, \ldots, i_\ell) \neq I_C}} \vol(\,u_{1}^{(i_1)}, \, u_{2}^{(i_2)}, \ldots, \,u_{\ell}^{(i_\ell)})\,. \label{eq:vl}
\end{equation}
For any permutation $\sigma \in \mathcal{S}_\ell$, define $\mathcal{F}(\sigma) := \{(i_1, i_2, \ldots, i_\ell): i_j \in \{\sigma(j), 0\} \}$.
Since $u_{i_1}^{(j)}$ and $u_{i_2}^{(j)}$ are linearly dependent, we can rewrite~\eqref{eq:vl} as
\begin{align}
    \vol(\proj X) &\geq \vol(\,u_{1}^{(0)}, \, u_{2}^{(2)}, \ldots, \,u_{\ell}^{(\ell)}) \; - \sum_{\tau \in \bigcup_{\sigma} \mathcal{F}(\sigma) \backslash I_C} \vol(\,u_{1}^{(\tau_1)}, \, u_{2}^{(\tau_2)}, \ldots, \,u_{\ell}^{(\tau_\ell)}) \notag \\
    &\geq \vol(\,u_{1}^{(0)}, \, u_{2}^{(2)}, \ldots, \,u_{\ell}^{(\ell)}) \; - \sum_{\sigma \in S_\ell}\sum_{\tau \in\mathcal{F}(\sigma) \backslash I_C} \vol(\,u_{1}^{(\tau_1)}, \, u_{2}^{(\tau_2)}, \ldots, \,u_{\ell}^{(\tau_\ell)})\,. \label{eq:a7}
\end{align}
For a fixed $\sigma \neq id_\ell$ and some $\tau \in \mathcal{F}(\sigma)$, let $I_{\tau}^0 := \{j \in [\ell]: \tau(j) = 0\}$ and $I_{\tau}^\sigma := [\ell]\backslash I_{\tau}^0$. Also, let $X_\tau = \{v_{\sigma(i)}: i \in I_\tau^\sigma\}$. Then
\begin{align*}
   \frac{\vol(\,u_{1}^{(\tau_1)}, \, u_{2}^{(\tau_2)}, \ldots, \,u_{\ell}^{(\tau_\ell)})}{\vol(\proj Y)} &= \frac{\vol\left( \bigcup_{i \in I_\tau^0} \, \{ u_{i}^{\perp} \}\right) \cdot \vol\left( \bigcup_{i \in I_\tau^\sigma} \, \{ a_{i, \sigma(i)} \proj v_{\sigma(i)})\}\right)}{\vol(\proj Y)}\\
   &\leq \prod_{i \in I_\tau^0} \norm{u_i^\perp} \cdot \prod_{i \in I_\tau^\sigma} |a_{i,\sigma(i)}| \cdot \frac{\vol\left( \bigcup_{i \in I_\tau^\sigma} \, \{  \proj v_{\sigma(i)})\}\right)}{\vol(\proj Y)} \\
   &\leq \prod_{i \in I_\tau^0} \norm{u_i^\perp} \cdot \prod_{i \in I_\tau^\sigma} |a_{i,\sigma(i)}| \cdot \frac{1}{\prod_{i \in I_\tau^0} \norm{v_{\sigma(i)}^\perp}} \tag{from Observation \ref{obs:log_vol_submodular}}\\
   &=  \prod_{i \in I_\tau^0} \frac{\norm{u_i}}{\norm{v^\perp_{\sigma(i)}}} \cdot \prod_{i \in I_\tau^\sigma} |a_{i,\sigma(i)}| = \prod_{i \in I_\tau^0} e^{-\Tilde{w}_0(u_i^\perp, v_{\sigma(i)})} \cdot \prod_{i \in I_\tau^\sigma} e^{-\Tilde{w}_0(u_i^\parallel, v_{\sigma(i)})}\,.
\end{align*}
Summing over all tuples $\tau \in \mathcal{F}(\sigma)$, we get
\begin{align}
    \sum_{\tau \in \mathcal{F}(\sigma)} \frac{\vol(\,u_{1}^{(\tau_1)}, \, u_{2}^{(\tau_2)}, \ldots, \,u_{\ell}^{(\tau_\ell)}) }{\vol(\proj Y)}  &\leq \prod_{i \in I_\tau^0} e^{-\Tilde{w}_0(u_i^\perp, v_{\sigma(i)})} \cdot \prod_{i \in I_\tau^\sigma} e^{-\Tilde{w}_0(u_i^\parallel, v_{\sigma(i)})} \notag \\
    &= \prod_{i = 1}^\ell \left(e^{-\Tilde{w}_0(u_i^\perp, v_{\sigma(i)}) }+ e^{-\Tilde{w}_0(u_i^\parallel, v_{\sigma(i)})}\right)\,. \label{eq:a8}
\end{align}
Let $W_C \in \mathbb{R}^{\ell \times \ell}$ be a matrix with $[W_C]_{i,j} = e^{-\Tilde{w}_0(u_i^\perp, v_{\sigma(i)}) }+ e^{-\Tilde{w}_0(u_i^\parallel, v_{\sigma(i)})}$. Then we can rewrite~\eqref{eq:a8} as
\begin{align}
    \sum_{\tau \in \mathcal{F}(\sigma)} \frac{\vol(\,u_{1}^{(\tau_1)}, \, u_{2}^{(\tau_2)}, \ldots, \,u_{\ell}^{(\tau_\ell)}) }{\vol(\proj Y)}  &\leq \prod_{i = 1}^\ell [W_C]_{i, \sigma(i)}\,. \label{eq:a13}
\end{align}
Similarly, the sum of tuples for the identity permutation $id_\ell$ gives
\begin{align}
   \frac{\vol(\,u_{1}^{(0)}, \, u_{2}^{(2)}, \ldots, \,u_{\ell}^{(\ell)})}{\vol(\proj Y)} &+ \sum_{\tau \in \mathcal{F}(id_\ell) \backslash I_C} \frac{\vol(\,u_{1}^{(\tau_1)}, \, u_{2}^{(\tau_2)}, \ldots, \,u_{\ell}^{(\tau_\ell)}) }{\vol(\proj X)}  \leq \prod_{i = 1}^\ell [W_C]_{i, i}\,. \label{eq:a9}
\end{align}
Plugging equation~\eqref{eq:a13} and equation~\eqref{eq:a9} in~\eqref{eq:a7}, we get
\begin{align}
    \frac{\vol(\proj X)}{\vol(\proj Y)} &\geq \frac{\vol(\,u_{1}^{(0)}, \, u_{2}^{(2)}, \ldots, \,u_{\ell}^{(\ell)})}{\vol(\proj Y)} -  \sum_{\sigma \neq {id}}\prod_{i = 1}^\ell [W_C]_{i, \sigma(i)} - \left(\prod_{i = 1}^\ell [W_C]_{i, i} - \frac{\vol(\,u_{1}^{(0)}, \, u_{2}^{(2)}, \ldots, \,u_{\ell}^{(\ell)})}{\vol(\proj Y)} \right) \notag \\
    &= \frac{2\vol(\,u_{1}^{(0)}, \, u_{2}^{(2)}, \ldots, \,u_{\ell}^{(\ell)})}{\vol(\proj Y)} -  \sum_{\sigma \neq {id}}\prod_{i = 1}^\ell [W_C]_{i, \sigma(i)} - \prod_{i = 1}^\ell [W_C]_{i, i} \notag  \\
    &= \frac{2\vol(\,u_{1}^{(0)}, \, u_{2}^{(2)}, \ldots, \,u_{\ell}^{(\ell)})}{\vol(\proj Y)} -  \perm(W_C) \,. \label{eq:a10}
\end{align}
From Lemma \ref{lem:permw}, we have
\begin{equation}
    \perm(W_C) \leq 1.56 \cdot \frac{\norm{u_1^\perp}}{\norm{v_1^\perp}} \cdot \prod_{i=2}^\ell |a_{i, i}|\,. \label{eq:a11}
\end{equation}
Note that \begin{equation}
     \frac{\vol(\,u_{1}^{(0)}, \, u_{2}^{(2)}, \ldots, \,u_{\ell}^{(\ell)})}{\vol(\proj Y)} = \frac{\norm{u_1^\perp}}{\norm{v_1^\perp}} \cdot \prod_{i=2}^\ell |a_{i, i}|\,. \label{eq:a12}
\end{equation}
Inserting the bounds from~\eqref{eq:a11} and~\eqref{eq:a12} in~\eqref{eq:a10} gives
\begin{align*}
    \frac{\vol(\proj X)}{\vol(\proj Y)}
    &\geq \frac{\norm{u_1^\perp}}{\norm{v_1^\perp}} \cdot \prod_{i=2}^\ell |a_{i, i}|\cdot (2 - 1.56) = 0.44 \cdot \frac{\norm{u_1^\perp}}{\norm{v_1^\perp}} \cdot \prod_{i=2}^\ell  |a_{i, i}|\,.
\end{align*}
Since $C$ is an $\Tilde{f}$-Violating cycle, $e^{-\Tilde{w}_0(C)} = \frac{\norm{u_1^\perp}}{\norm{v_1^\perp}} \cdot \prod_{i=2}^\ell |a_{i, i}| \geq \Tilde{f}(\ell)$. Therefore, \begin{align*}
   \frac{\vol(S\Delta C)}{ \vol(S)} = \frac{\vol(\proj X)}{\vol(\proj Y)}
    &\geq 0.44 \cdot \Tilde{f}(\ell) \geq 2 \,.
\end{align*}
\end{proof}
